function converterDados(){const n=parseFloat(document.getElementById("input-valor").value),s=document.getElementById("select-unidade").value,o=document.getElementById("resultado-container");if(isNaN(n)){o.innerHTML="Aguardando valor...";return}const e={B:1,KB:1e3,MB:1e6,GB:1e9,TB:1e12},i=n*e[s];let t='<div class="result-list">';for(let n in e)if(n!==s){let s=i/e[n],o=s%1===0?s:s.toFixed(4);t+=`<p><strong>${o}</strong> ${n}</p>`}t+="</div>",o.innerHTML=t}document.getElementById("input-valor").addEventListener("input",converterDados),document.getElementById("select-unidade").addEventListener("change",converterDados)